-- =============================================================================
-- ORDS step 1: enable the schema, create roles, privileges and OAuth2 clients
-- STATUS: written, NOT executed. Verify the ORDS PL/SQL API signatures against the ORDS version certified
-- for your APEX 24.1 installation (ORDS 'Developer Guide > PL/SQL API').
-- Run as the REST-enabled schema (see 05_INTEGRATIONS/README.md for the schema decision).
-- Substitution variables:  &schema  &support_email
-- Client SECRETS are generated by ORDS. Read them once with the SELECT at the end, store them in your secret
-- manager and never commit them.
-- =============================================================================
SET DEFINE ON
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT FAILURE ROLLBACK

BEGIN
  ORDS.enable_schema(p_enabled             => TRUE,
                     p_schema              => UPPER('&schema'),
                     p_url_mapping_type    => 'BASE_PATH',
                     p_url_mapping_pattern => 'lms',
                     p_auto_rest_auth      => TRUE);
  COMMIT;
END;
/

-- ---------------------------------------------------------------- roles ---------
DECLARE
  PROCEDURE role_(p_name VARCHAR2) IS
  BEGIN
    ORDS.create_role(p_role_name => p_name);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE NOT IN (-20000, -1) THEN DBMS_OUTPUT.put_line('role ' || p_name || ': ' || SQLERRM); END IF;   -- already exists
  END role_;
BEGIN
  role_('lms.hr_sync');        -- HR integration: POST /hr/employees
  role_('lms.catalog_read');   -- read-only catalog consumers (intranet portal, mobile shell)
  role_('lms.ops');            -- monitoring: GET /ops/health
  COMMIT;
END;
/

-- ------------------------------------------------------------ privileges -------
-- /public/* is intentionally NOT protected: it serves only the minimal certificate verification answer and is
-- rate limited (CERT_VERIFY) at the proxy and in PL/SQL.
BEGIN
  ORDS.define_privilege(p_privilege_name => 'lms.hr_sync.priv',
                        p_roles          => owa.vc_arr('lms.hr_sync'),
                        p_patterns       => owa.vc_arr('/hr/*'),
                        p_modules        => owa.vc_arr('lms.hr'),
                        p_label          => 'LMS HR synchronisation',
                        p_description    => 'Create/update employees from the HR system');
  ORDS.define_privilege(p_privilege_name => 'lms.catalog.priv',
                        p_roles          => owa.vc_arr('lms.catalog_read'),
                        p_patterns       => owa.vc_arr('/catalog/*'),
                        p_modules        => owa.vc_arr('lms.catalog'),
                        p_label          => 'LMS catalog read',
                        p_description    => 'Read published course catalog');
  ORDS.define_privilege(p_privilege_name => 'lms.ops.priv',
                        p_roles          => owa.vc_arr('lms.ops'),
                        p_patterns       => owa.vc_arr('/ops/*'),
                        p_modules        => owa.vc_arr('lms.ops'),
                        p_label          => 'LMS operations',
                        p_description    => 'Health endpoint for monitoring');
  COMMIT;
EXCEPTION WHEN OTHERS THEN
  DBMS_OUTPUT.put_line('privileges: ' || SQLERRM || ' (re-running is safe if they already exist)');
END;
/

-- ------------------------------------------------------- OAuth2 clients ---------
-- client_credentials grant = machine-to-machine. A client represents an application, never an end user, so these
-- endpoints must not return personal data about a specific learner (they do not).
DECLARE
  PROCEDURE client_(p_name VARCHAR2, p_desc VARCHAR2, p_priv VARCHAR2, p_role VARCHAR2) IS
    l_n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO l_n FROM user_ords_clients WHERE name = p_name;
    IF l_n = 0 THEN
      OAUTH.create_client(p_name => p_name, p_grant_type => 'client_credentials', p_owner => 'LMS',
                          p_description => p_desc, p_support_email => '&support_email',
                          p_privilege_names => p_priv);
      OAUTH.grant_client_role(p_client_name => p_name, p_role_name => p_role);
    END IF;
  END client_;
BEGIN
  client_('lms_hr_sync',   'HR synchronisation job',          'lms.hr_sync.priv', 'lms.hr_sync');
  client_('lms_portal_ro', 'Read-only catalog consumer',      'lms.catalog.priv', 'lms.catalog_read');
  client_('lms_monitor',   'Monitoring system health probe',  'lms.ops.priv',     'lms.ops');
  COMMIT;
END;
/

-- Retrieve the generated credentials ONCE (do not spool this to a file that is kept):
--   SELECT name, client_id, client_secret FROM user_ords_clients WHERE name LIKE 'lms\_%' ESCAPE '\';
-- Rotate on a schedule and on any suspicion of exposure (verify procedure name for your ORDS version):
--   BEGIN OAUTH.rotate_client_secret(p_client_name => 'lms_hr_sync'); COMMIT; END;
